SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsWorkerDirectoryRequest
{
    DataAreaId dataAreaId;
    str        actingUserName;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

/// <summary>
/// Must belong to a current supervisor - re-checked server-side, same as
/// HSMobileOpsSetModulePermissionRequest::parmActingUserName. The worker directory is only
/// ever browsed from the Admin Center, which the app itself already hides from a
/// non-supervisor, but that client-side gate is UX, not security - see this service
/// operation's own doc.
/// </summary>
[DataMemberAttribute('ActingUserName')]
public str parmActingUserName(str _value = actingUserName)
{
    actingUserName = _value;
    return actingUserName;
}
